def rule_cover_page_listing_sentence(doc: dict) -> list[dict]:
    """Match cover-page narrative sentences stating the common stock is listed on an exchange."""
    import re
    try:
        out = []
        for span in doc.get("texts", []):
            combined = " ".join([span.get("text", "") or "", span.get("text_span", "") or ""])
            if span.get("page_no") <= 5 and re.search(r'common stock .* listed on .*?(new york stock exchange|nasdaq)', combined, re.I):
                out.append(span)
        return out
    except Exception:
        return []

def rule_exchange_value_following_nasdaq_or_nyse_symbol(doc: dict) -> list[dict]:
    """Match exchange spans near stock ticker symbols on the cover page."""
    import re
    try:
        texts = doc.get("texts", [])
        out = []
        for i, s in enumerate(texts):
            t = (s.get("text") or "").strip()
            if s.get("page_no") == 1 and re.fullmatch(r'[A-Z]{2,5}', t or ""):
                for j in range(i, min(len(texts), i + 6)):
                    s2 = texts[j]
                    if s2.get("page_no") == 1 and re.search(r'new york stock exchange|nasdaq|global select market', s2.get("text", "") or "", re.I):
                        out.append(s2)
        return out
    except Exception:
        return []

def rule_exchange_after_name_of_exchange_header(doc: dict) -> list[dict]:
    """Match the next few spans after a standalone 'Name of each exchange on which registered' header."""
